'use client';

import { useEffect, useState } from 'react';
import Layout from '@/components/layout/layout';
import AuthGuard from '@/components/auth/auth-guard';
import StatCard from '@/components/dashboard/stat-card';
import RecentActivity from '@/components/dashboard/recent-activity';

import apiClient, { endpoints } from '@/lib/api';

// Types
interface DashboardSummary {
  total_products: number;
  total_branches: number;
  total_sales_today: number;
  total_revenue_today: number;
  low_stock_count: number;
  out_of_stock_count: number;
  pending_transfers: number;
}

// Internal activities type 
interface DashboardActivity {
  id: string;
  type: 'sale' | 'transfer' | 'stock_adjustment' | 'new_product';
  description: string;
  user: string;
  timestamp: string;
  branch: string;
}

export default function DashboardPage() {
  const [summary, setSummary] = useState<DashboardSummary | null>(null);
  const [activities, setActivities] = useState<DashboardActivity[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchDashboardData = async () => {
      try {
        setLoading(true);
        const [summaryRes, alertsRes] = await Promise.all([
          apiClient.get(endpoints.dashboard.summary),
          apiClient.get(endpoints.dashboard.alerts)
        ]);

        setSummary(summaryRes.data);
        // Map activities if available, otherwise use empty
        setActivities(alertsRes.data || []);
        setLoading(false);
      } catch (err) {
        console.error('Dashboard fetch error:', err);
        setError('Failed to load dashboard data. Please check if the API is running.');
        setLoading(false);
      }
    };

    fetchDashboardData();
  }, []);

  if (loading) {
    return (
      <Layout>
        <div className="animate-pulse space-y-8">
          <div className="h-8 bg-surface rounded w-1/4"></div>
          <div className="grid grid-cols-1 gap-5 sm:grid-cols-2 lg:grid-cols-4">
            {[...Array(4)].map((_, i) => (
              <div key={i} className="bg-surface rounded-lg h-32"></div>
            ))}
          </div>
          <div className="grid grid-cols-1 gap-5 lg:grid-cols-3">
            {[...Array(3)].map((_, i) => (
              <div key={i} className="bg-surface rounded-lg h-32"></div>
            ))}
          </div>
        </div>
      </Layout>
    );
  }

  if (error || !summary) {
    return (
      <Layout>
        <div className="bg-error-light border border-error/20 rounded-lg p-4">
          <div className="text-error font-medium">{error || 'Something went wrong'}</div>
          <button
            onClick={() => window.location.reload()}
            className="mt-2 text-sm text-primary hover:underline"
          >
            Try Again
          </button>
        </div>
      </Layout>
    );
  }

  return (
    <AuthGuard>
      <Layout>
        <div className="space-y-6 sm:space-y-8">
          {/* Header */}
          <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
            <div>
              <h1 className="text-2xl sm:text-3xl font-black text-primary tracking-tight">Dashboard</h1>
              <p className="text-sm text-text-secondary mt-1">Welcome back! Here's what's happening with your store today.</p>
            </div>
          </div>

          {/* Stats Grid */}
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 sm:gap-6">
            <StatCard
              title="Total Products"
              value={summary.total_products}
              change={12}
              changeType="increase"
              icon="products"
            />
            <StatCard
              title="Total Branches"
              value={summary.total_branches}
              change={0}
              icon="branches"
            />
            <StatCard
              title="Sales Today"
              value={summary.total_sales_today}
              change={8}
              changeType="increase"
              icon="revenue"
            />
            <StatCard
              title="Revenue Today"
              value={summary.total_revenue_today}
              change={15}
              changeType="increase"
              icon="revenue"
            />
          </div>

          {/* Additional Stats */}
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4 sm:gap-6">
            <div className="card p-4 sm:p-6">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-sm font-medium text-text-secondary">Low Stock Items</p>
                  <p className="text-2xl sm:text-3xl font-bold text-warning">{summary.low_stock_count}</p>
                </div>
                <div className="p-3 bg-warning/10 rounded-xl">
                  <span className="text-2xl">⚠️</span>
                </div>
              </div>
            </div>
            
            <div className="card p-4 sm:p-6">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-sm font-medium text-text-secondary">Out of Stock</p>
                  <p className="text-2xl sm:text-3xl font-bold text-error">{summary.out_of_stock_count}</p>
                </div>
                <div className="p-3 bg-error/10 rounded-xl">
                  <span className="text-2xl">🚫</span>
                </div>
              </div>
            </div>
            
            <div className="card p-4 sm:p-6">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-sm font-medium text-text-secondary">Pending Transfers</p>
                  <p className="text-2xl sm:text-3xl font-bold text-info">{summary.pending_transfers}</p>
                </div>
                <div className="p-3 bg-info/10 rounded-xl">
                  <span className="text-2xl">🔄</span>
                </div>
              </div>
            </div>
          </div>

          {/* Quick Actions */}
          <div className="card p-4 sm:p-6">
            <h2 className="text-lg sm:text-xl font-bold text-primary mb-4">Quick Actions</h2>
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3 sm:gap-4">
              <button className="flex items-center justify-center space-x-2 p-3 bg-primary/10 rounded-xl hover:bg-primary/20 transition-colors">
                <span className="text-xl">🛒</span>
                <span className="text-sm font-medium text-primary">New Sale</span>
              </button>
              <button className="flex items-center justify-center space-x-2 p-3 bg-success/10 rounded-xl hover:bg-success/20 transition-colors">
                <span className="text-xl">📦</span>
                <span className="text-sm font-medium text-success">Add Product</span>
              </button>
              <button className="flex items-center justify-center space-x-2 p-3 bg-info/10 rounded-xl hover:bg-info/20 transition-colors">
                <span className="text-xl">👥</span>
                <span className="text-sm font-medium text-info">Add Customer</span>
              </button>
              <button className="flex items-center justify-center space-x-2 p-3 bg-warning/10 rounded-xl hover:bg-warning/20 transition-colors">
                <span className="text-xl">📊</span>
                <span className="text-sm font-medium text-warning">View Reports</span>
              </button>
            </div>
          </div>

          {/* Recent Activity */}
          <div className="card p-4 sm:p-6">
            <h2 className="text-lg sm:text-xl font-bold text-primary mb-4">Recent Activity</h2>
            <RecentActivity activities={activities} />
          </div>
        </div>
      </Layout>
    </AuthGuard>
  );
}
